var options={roomId:1,types:{words:{name:'Ohana Words',min:2,max:4},tictac:{name:'Tic-Tac-Toe',min:2,max:2},memory:{name:'Memory Match',min:1,max:2},checkers:{name:'Checkers',min:2,max:2},mahjong:{name:'Ohana Mahjong',min:1,max:4},handfoot:{name:'Ohanda & Foot',min:2,max:4},spades:{name:'Ohana Spades',min:4,max:4},shuffle:{name:'Ohana Shuffle',min:2,max:6},solo:{name:'Fictional solo only',min:1,max:1}},members:Array.from({length:8},(_,i)=>({id:i+1,name:'Fixture Person '+(i+1),blocked_types:[]})).concat([{id:-1,name:'Fixture Robot'},{id:90,name:'CodexTest'}]),games:[{id:11,type:'words',status:'playing',players:[1,2],pending_members:[]},{id:12,type:'words',status:'waiting',players:[1],pending_members:[3]},{id:13,type:'words',status:'waiting',players:[4],pending_members:[1]}]};
