function committed(body){if(!receipts.has(body.request_id)){receipts.set(body.request_id,JSON.parse(JSON.stringify(body)));for(const id of body.member_ids)options.games.push({id:100+id,type:body.type,status:'waiting',players:[1],pending_members:[id]});}return {ok:true};}
var api=async(path,body,method,room)=>{calls.push({path,body,method,room});if(path!=='/api/game/invitations')throw Error('Fixture blocks all other requests');if(method==='GET'){if(nextGet){const fn=nextGet;nextGet=null;return fn();}return JSON.parse(JSON.stringify(options));}if(nextPost){const fn=nextPost;nextPost=null;return fn(body);}return committed(body);};
